/**
 * The playground's seed manifests: one per demo, generated by `scripts/make-seeds.mjs` from a `demos/<id>.demo.json`
 * (the demo's type, its agent script) and the artifact folder it names (`files`). Loaded lazily, one per page.
 */

import type { DbWrite, JsonRecord } from '@open-artifact/runtime';

/** One file of the seed: UTF-8 text, or base64 for anything else. */
export type SeedFile = { text: string } | { base64: string };

/** Appends `value` to the array `field` of a JSON document or file, once (a db document path or a project file). */
export interface AppendOrder {
  path: string;
  field: string;
  value: string;
}

/**
 * One prepared change the simulated agent makes. Strings may hold `{{n}}` (the agent's turn, from 1) and `{{request}}`
 * (what the person asked, shortened; HTML-escaped inside `files`).
 */
export type AgentEdit =
  | { kind: 'db'; writes: DbWrite[]; appendOrder?: AppendOrder }
  | { kind: 'files'; files: Record<string, string>; appendOrder?: AppendOrder }
  | DocEdit
  | SheetEdit;

/**
 * A paragraph the agent writes into a doc, through the Docs host's own agent call (`host.agentCall`), so the open page
 * hears it as the agent's edit. `tab`: the tab's name; by default the tab the thread is on, else the first tab. `at`:
 * `top` puts it right under the tab's first block (its title line), `end` after its last. Sets `{{tab}}` (the tab's
 * name) for the reply.
 */
export interface DocEdit {
  kind: 'doc';
  tab?: string;
  at: 'top' | 'end';
  text: string;
}

/**
 * A cell the agent writes in a workbook, through the Sheets store's own agent update (`store.agentUpdate`), so the
 * engine works every formula out again and the open page hears the agent's edit. `cell`: an A1 reference on `sheet`.
 * `watch`: a cell (a total) whose value before and after sets `{{was}}` and `{{now}}` for the reply.
 */
export interface SheetEdit {
  kind: 'sheet';
  sheet: string;
  cell: string;
  value: number | string;
  watch?: { sheet: string; cell: string };
}

/** One scripted turn: the comment the agent posts and what it changes. */
export interface AgentResponse {
  reply: string;
  edits: AgentEdit[];
}

/** How the simulated agent behaves on this demo. Turns go through `responses` in order, then start over. */
export interface AgentScript {
  name: string;
  /** How long the agent "works" before it answers. */
  thinkMs: number;
  responses: AgentResponse[];
}

export interface SeedManifest {
  id: string;
  type: string;
  typeTitle: string;
  /** The test-artifacts folder it was made from. */
  source: string;
  title?: string;
  agent: AgentScript;
  /** Artifact-relative path → content (`project/…` files, `db/<collection>/<id>.json` documents). */
  files: Record<string, SeedFile>;
}

const manifests = import.meta.glob<SeedManifest>('./generated/*.json', { import: 'default' });

/** The ids of the generated demos. */
export const SEED_IDS: string[] = Object.keys(manifests).map((key) => key.replace(/^.*\/(.+)\.json$/, '$1')).sort();

/** Loads one demo's manifest; `null` when there is none by that id. */
export async function loadSeed(id: string): Promise<SeedManifest | null> {
  const load = manifests[`./generated/${id}.json`];
  return load ? load() : null;
}

/** The seed's document store: `db/<collection…>/<id>.json` files as document paths and data. */
export function seedDocuments(seed: SeedManifest): Map<string, JsonRecord> {
  const docs = new Map<string, JsonRecord>();
  for (const [path, file] of Object.entries(seed.files)) {
    const match = /^db\/(.+)\.json$/.exec(path);
    if (!match || !('text' in file)) continue;
    docs.set(match[1]!, JSON.parse(file.text) as JsonRecord);
  }
  return docs;
}

const bytesOf = (file: SeedFile): Uint8Array<ArrayBuffer> =>
  'text' in file ? new TextEncoder().encode(file.text) : Uint8Array.from(atob(file.base64), (c) => c.charCodeAt(0));

/** The seed's project files as bytes, by artifact-relative path (`project/…`; not `db/` documents, not `_blobs/`). */
export function seedFiles(seed: SeedManifest): Map<string, Uint8Array> {
  const files = new Map<string, Uint8Array>();
  for (const [path, file] of Object.entries(seed.files)) {
    if (path.startsWith('db/') || path.startsWith('_blobs/')) continue;
    files.set(path, bytesOf(file));
  }
  return files;
}

const BLOB_TYPES: Record<string, string> = {
  csv: 'text/csv',
  tsv: 'text/tab-separated-values',
  json: 'application/json',
  txt: 'text/plain',
  mp3: 'audio/mpeg',
  wav: 'audio/wav',
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  webp: 'image/webp',
  svg: 'image/svg+xml',
};

/** The seed's stored files (`_blobs/<id>.<ext>`, what a type server serves at `/_blob/<id>`), by id. */
export function seedBlobs(seed: SeedManifest): Map<string, Blob> {
  const blobs = new Map<string, Blob>();
  for (const [path, file] of Object.entries(seed.files)) {
    const match = /^_blobs\/([0-9a-f]{32})(?:\.([A-Za-z0-9]+))?$/.exec(path);
    if (!match) continue;
    blobs.set(match[1]!, new Blob([bytesOf(file)], { type: BLOB_TYPES[(match[2] ?? '').toLowerCase()] ?? 'application/octet-stream' }));
  }
  return blobs;
}

/**
 * The seed with every `/_blob/<id>` address of its text files and documents replaced by `urls`' address for that id
 * (a `blob:` URL of this page): a static site serves nothing at `/_blob/`, and pages accept `blob:` addresses where
 * they accept stored ones (data's file sources, motion's audio).
 */
export function withBlobUrls(seed: SeedManifest, urls: Map<string, string>): SeedManifest {
  if (!urls.size) return seed;
  const files: Record<string, SeedFile> = {};
  for (const [path, file] of Object.entries(seed.files)) {
    files[path] = 'text' in file ? { text: file.text.replace(/\/?_blob\/([0-9a-f]{32})/g, (all, id: string) => urls.get(id) ?? all) } : file;
  }
  return { ...seed, files };
}
